#' Lymph Node Ratio
#'
#' Computes the lymph node ratio (LNR = positive nodes / examined nodes) for 
#' each patient, assesses nodal-yield adequacy against a minimum-examined 
#' threshold, and relates LNR to a survival outcome. LNR can be stratified 
#' either by established category thresholds or by a data-driven optimal 
#' cutpoint chosen to maximize the log-rank separation, and the resulting 
#' strata are compared with Kaplan-Meier / log-rank testing. LNR is an 
#' established prognostic factor across colorectal, gastric, breast, and 
#' head-and-neck cancers, and is more robust than absolute node counts when 
#' nodal yield varies between specimens.
#' 
#' @param data The data as a data frame (one row per patient).
#' @param positiveNodes Number of lymph nodes containing metastatic carcinoma.
#' @param examinedNodes Total number of lymph nodes examined.
#' @param minYield Minimum examined-node count considered an adequate nodal
#'   yield (e.g. 12 for colorectal).
#' @param stratMethod How to categorize LNR for the survival comparison.
#' @param thresholds Comma-separated LNR cut points for the
#'   established-threshold stratification (e.g. "0.2, 0.5" gives Low /
#'   Intermediate / High).
#' @param survivalTime Follow-up time for the survival comparison.
#' @param survivalStatus Event indicator for the survival comparison.
#' @param eventLevel Level of the status variable representing the event.
#' @param conf_level Confidence level for hazard-ratio estimates.
#' @param showRatioSummary Summary statistics of LNR and nodal yield across
#'   the cohort.
#' @param showStrata Table of LNR strata with n, events, and median survival.
#' @param showPlot Distribution of LNR (and strata) or the survival curves by
#'   stratum.
#' @param showSummary Plain-language summary.
#' @param showExplanation Explanation of LNR and its prognostic use.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$ratioTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$strataTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$explanation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$addRatioToData} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$addStratumToData} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$ratioTable$asDF}
#'
#' \code{as.data.frame(results$ratioTable)}
#'
#' @export
lymphnoderatio <- function(
    data,
    positiveNodes,
    examinedNodes,
    minYield = 12,
    stratMethod = "fixed",
    thresholds = "0.2, 0.5",
    survivalTime = NULL,
    survivalStatus = NULL,
    eventLevel,
    conf_level = 0.95,
    showRatioSummary = TRUE,
    showStrata = TRUE,
    showPlot = TRUE,
    showSummary = FALSE,
    showExplanation = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("lymphnoderatio requires jmvcore to be installed (restart may be required)")

    if ( ! missing(positiveNodes)) positiveNodes <- jmvcore::resolveQuo(jmvcore::enquo(positiveNodes))
    if ( ! missing(examinedNodes)) examinedNodes <- jmvcore::resolveQuo(jmvcore::enquo(examinedNodes))
    if ( ! missing(survivalTime)) survivalTime <- jmvcore::resolveQuo(jmvcore::enquo(survivalTime))
    if ( ! missing(survivalStatus)) survivalStatus <- jmvcore::resolveQuo(jmvcore::enquo(survivalStatus))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(positiveNodes), positiveNodes, NULL),
            `if`( ! missing(examinedNodes), examinedNodes, NULL),
            `if`( ! missing(survivalTime), survivalTime, NULL),
            `if`( ! missing(survivalStatus), survivalStatus, NULL))


    options <- lymphnoderatioOptions$new(
        positiveNodes = positiveNodes,
        examinedNodes = examinedNodes,
        minYield = minYield,
        stratMethod = stratMethod,
        thresholds = thresholds,
        survivalTime = survivalTime,
        survivalStatus = survivalStatus,
        eventLevel = eventLevel,
        conf_level = conf_level,
        showRatioSummary = showRatioSummary,
        showStrata = showStrata,
        showPlot = showPlot,
        showSummary = showSummary,
        showExplanation = showExplanation)

    analysis <- lymphnoderatioClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

